    "settings.experimental.nativeNotebookTools.title": "\uB124\uC774\uD2F0\uBE0C \uB178\uD2B8\uBD81 \uB3C4\uAD6C",
    "settings.experimental.nativeNotebookTools.description": "VS Code \uB178\uD2B8\uBD81\uC744 \uC77D\uACE0, \uD3B8\uC9D1\uD558\uACE0, \uC2E4\uD589\uD558\uB294 \uC2E4\uD5D8\uC801 \uB3C4\uAD6C\uB97C \uD65C\uC131\uD654\uD569\uB2C8\uB2E4",
    "settings.experimental.continueOnDeny.title": "\uAC70\uBD80 \uC2DC \uACC4\uC18D",
    "settings.experimental.continueOnDeny.description": "\uAD8C\uD55C\uC774 \uAC70\uBD80\uB418\uBA74 \uC5D0\uC774\uC804\uD2B8 \uB8E8\uD504 \uACC4\uC18D",
    "settings.sandboxing.title": "\uC0CC\uB4DC\uBC15\uC2A4",
    "settings.sandboxing.network.title": "\uB124\uD2B8\uC6CC\uD06C \uC561\uC138\uC2A4 \uC81C\uD55C",
    "settings.sandboxing.network.description": "\uBAA8\uB378\uC5D0\uC11C \uC2DC\uC791\uB41C \uBA85\uB839 \uBC0F HTTP \uB3C4\uAD6C\uC758 \uC9C1\uC811\uC801\uC778 \uC544\uC6C3\uBC14\uC6B4\uB4DC \uC561\uC138\uC2A4\uB97C \uCC28\uB2E8\uD569\uB2C8\uB2E4. \uC81C\uD55C\uC774 \uC801\uC6A9\uB418\uB294 \uB3D9\uC548 \uB85C\uCEEC \uBC0F \uC6D0\uACA9 MCP \uB3C4\uAD6C\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uACF5\uAE09\uC790 \uD2B8\uB798\uD53D\uACFC \uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uD50C\uB7EC\uADF8\uC778 \uD6C4\uD06C\uB294 \uC774 \uC81C\uD55C\uC758 \uC801\uC6A9 \uB300\uC0C1\uC774 \uC544\uB2D9\uB2C8\uB2E4.",
    "settings.sandboxing.allowedHosts.title": "\uD5C8\uC6A9\uB41C \uB124\uD2B8\uC6CC\uD06C \uB300\uC0C1",
    "settings.sandboxing.allowedHosts.description": "\uC0CC\uB4DC\uBC15\uC2A4 \uCC98\uB9AC\uB41C HTTP \uBC0F HTTPS \uD504\uB85D\uC2DC \uD2B8\uB798\uD53D\uC758 DNS \uD638\uC2A4\uD2B8 \uBC0F \uD3EC\uD2B8 \uB300\uC0C1\uC785\uB2C8\uB2E4. GitHub CLI \uBC0F HTTPS Git\uC5D0\uB294 \uC77C\uBC18\uC801\uC73C\uB85C github.com:443 \uBC0F api.github.com:443\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4. \uBCC0\uACBD \uC0AC\uD56D\uC740 \uC0C8 \uC138\uC158\uC5D0 \uC801\uC6A9\uB429\uB2C8\uB2E4.",
    "settings.sandboxing.writablePaths.title": "\uCD94\uAC00 \uC4F0\uAE30 \uAC00\uB2A5 \uACBD\uB85C",
    "settings.sandboxing.writablePaths.description": "\uC0CC\uB4DC\uBC15\uC2A4\uC5D0\uC11C \uC4F0\uAE30\uB97C \uD5C8\uC6A9\uD558\uB294 \uCD94\uAC00 \uD30C\uC77C\uC2DC\uC2A4\uD15C \uACBD\uB85C(\uC608: /tmp, /var/log). \uC0CC\uB4DC\uBC15\uC2A4\uAC00 \uD65C\uC131\uD654\uB418\uBA74 \uAE30\uBCF8 \uC4F0\uAE30 \uAC00\uB2A5 \uACBD\uB85C\uC640 \uBCD1\uD569\uB429\uB2C8\uB2E4.",
    "settings.experimental.swePruner.title": "SWE-Pruner",
    "settings.experimental.swePruner.description": "SWE-Pruner \uD65C\uC131\uD654: \uC5D0\uC774\uC804\uD2B8\uAC00 \uC81C\uACF5\uD55C \uCD08\uC810 \uC9C8\uBB38\uC5D0 \uB530\uB77C \uC791\uC5C5 \uB9E5\uB77D\uC744 \uACE0\uB824\uD558\uC5EC \uC77D\uAE30, \uAC80\uC0C9 \uBC0F \uC178 \uB3C4\uAD6C\uC758 \uB300\uC6A9\uB7C9 \uCD9C\uB825\uC744 \uD504\uB8E8\uB2DD\uD569\uB2C8\uB2E4",
    "settings.experimental.swePrunerModel.title": "SWE-Pruner \uBAA8\uB378",
    "settings.experimental.swePrunerModel.description": "\uB3C4\uAD6C \uCD9C\uB825\uC744 \uC815\uB9AC\uD558\uB294 \uB370 \uC0AC\uC6A9\uD558\uB294 \uBAA8\uB378. \uAE30\uBCF8\uAC12\uC740 \uAD6C\uC131\uB41C \uC18C\uD615 \uBAA8\uB378\uC785\uB2C8\uB2E4",
