    "settings.agentBehaviour.temperature.title": "\uC628\uB3C4",
    "settings.agentBehaviour.temperature.description": "AI \uC751\uB2F5\uC758 \uBB34\uC791\uC704\uC131\uC744 \uC870\uC808\uD569\uB2C8\uB2E4(0\u20132). \uB0AE\uC740 \uAC12(\uC608: 0.2)\uC740 \uC9D1\uC911\uB418\uACE0 \uC77C\uAD00\uB41C \uCD9C\uB825\uC744 \uC0DD\uC131\uD569\uB2C8\uB2E4. \uB192\uC740 \uAC12(\uC608: 1.0)\uC740 \uB354 \uB2E4\uC591\uD558\uACE0 \uCC3D\uC758\uC801\uC778 \uC751\uB2F5\uC744 \uC0DD\uC131\uD569\uB2C8\uB2E4. \uBAA8\uB378 \uAE30\uBCF8\uAC12\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBE44\uC6CC \uB450\uC138\uC694.",
    "settings.agentBehaviour.topP.title": "Top P",
    "settings.agentBehaviour.topP.description": "\uD575 \uC0D8\uD50C\uB9C1 \uC784\uACC4\uAC12\uC785\uB2C8\uB2E4(0\u20131). \uB204\uC801 \uD655\uB960\uC774 P\uC5D0 \uB3C4\uB2EC\uD558\uB294 \uAC00\uC7A5 \uC791\uC740 \uD1A0\uD070 \uC9D1\uD569\uC73C\uB85C \uC120\uD0DD\uC9C0\uB97C \uC81C\uD55C\uD569\uB2C8\uB2E4. \uB0AE\uC740 \uAC12\uC740 \uCD9C\uB825\uC744 \uB354 \uC9D1\uC911\uB418\uAC8C \uD558\uACE0, \uB192\uC740 \uAC12\uC740 \uB354 \uB9CE\uC740 \uB2E4\uC591\uC131\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. \uBAA8\uB378 \uAE30\uBCF8\uAC12\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBE44\uC6CC \uB450\uC138\uC694.",
    "settings.agentBehaviour.maxSteps.title": "\uCD5C\uB300 \uB2E8\uACC4",
    "settings.agentBehaviour.maxSteps.description": "\uC5D0\uC774\uC804\uD2B8\uC758 \uCD5C\uB300 \uB2E8\uACC4 \uC218\uC785\uB2C8\uB2E4. \uD55C\uB3C4\uC5D0 \uB3C4\uB2EC\uD558\uBA74 \uC5D0\uC774\uC804\uD2B8\uB294 \uB3C4\uAD6C \uC0AC\uC6A9\uC744 \uC911\uB2E8\uD558\uACE0 \uCD5C\uC885 \uC751\uB2F5\uC744 \uC81C\uACF5\uD558\uB77C\uB294 \uC9C0\uC2DC\uB97C \uBC1B\uC2B5\uB2C8\uB2E4. \uBCF5\uC7A1\uD55C \uB2E4\uB2E8\uACC4 \uC791\uC5C5\uC5D0\uB294 \uAC12\uC744 \uB192\uC774\uACE0, \uC751\uB2F5\uC744 \uB354 \uC9E7\uACE0 \uC608\uCE21 \uAC00\uB2A5\uD558\uAC8C \uC720\uC9C0\uD558\uB824\uBA74 \uB0AE\uCD94\uC138\uC694.",
    "settings.agentBehaviour.hidden.title": "\uC228\uAE40",
    "settings.agentBehaviour.hidden.description": "\uCC44\uD305 \uC785\uB825\uC758 \uBAA8\uB4DC \uC804\uD658\uAE30\uC5D0\uC11C \uC774 \uC5D0\uC774\uC804\uD2B8\uB97C \uC228\uAE30\uAE30",
    "settings.agentBehaviour.disable.title": "\uBE44\uD65C\uC131\uD654\uB428",
    "settings.agentBehaviour.disable.description": "\uC774 \uC5D0\uC774\uC804\uD2B8\uB97C \uC644\uC804\uD788 \uBE44\uD65C\uC131\uD654 \u2014 \uC5B4\uB514\uC5D0\uB3C4 \uD45C\uC2DC\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
    "settings.agentBehaviour.badge.hidden": "\uC228\uAE40",
    "settings.agentBehaviour.badge.disabled": "\uBE44\uD65C\uC131\uD654\uB428",
    "settings.agentBehaviour.badge.deprecated": "\uBE44\uAD8C\uC7A5",
    "settings.agentBehaviour.discoveredSkills": "\uAC80\uC0C9\uB41C \uC2A4\uD0AC",
    "settings.agentBehaviour.noSkillsFound": "\uC2A4\uD0AC\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC2A4\uD0AC\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uC544\uB798\uC5D0 \uC2A4\uD0AC \uD3F4\uB354 \uACBD\uB85C \uB610\uB294 URL\uC744 \uCD94\uAC00\uD558\uC138\uC694.",
    "settings.agentBehaviour.availableModes": "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uC0AC\uC6A9\uC790 \uC815\uC758 \uBAA8\uB4DC",
    "settings.agentBehaviour.noAgentsFound": "\uC5D0\uC774\uC804\uD2B8\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "settings.agentBehaviour.createMode": "\uC0C8 \uBAA8\uB4DC \uB9CC\uB4E4\uAE30",
    "settings.agentBehaviour.createMode.name": "\uC774\uB984",
    "settings.agentBehaviour.createMode.name.placeholder": "\uC608: reviewer",
    "settings.agentBehaviour.createMode.name.description": "\uBAA8\uB4DC\uC758 \uACE0\uC720 \uC2DD\uBCC4\uC790. \uC18C\uBB38\uC790, \uC22B\uC790, \uD558\uC774\uD508\uB9CC \uC0AC\uC6A9\uD558\uC138\uC694.",
    "settings.agentBehaviour.createMode.description": "\uC124\uBA85",
    "settings.agentBehaviour.createMode.description.placeholder": "\uC608: \uD488\uC9C8 \uBC0F \uBAA8\uBC94 \uC0AC\uB840\uB97C \uC704\uD574 \uCF54\uB4DC\uB97C \uAC80\uD1A0\uD569\uB2C8\uB2E4",
    "settings.agentBehaviour.createMode.description.help": "\uC774 \uBAA8\uB4DC\uAC00 \uD558\uB294 \uC77C\uC5D0 \uB300\uD55C \uAC04\uB2E8\uD55C \uC124\uBA85.",
    "settings.agentBehaviour.createMode.prompt": "\uC2DC\uC2A4\uD15C \uD504\uB86C\uD504\uD2B8",
    "settings.agentBehaviour.createMode.prompt.placeholder": "\uC608: \uB2F9\uC2E0\uC740 \uCF54\uB4DC \uB9AC\uBDF0\uC5B4\uC785\uB2C8\uB2E4. \uCF54\uB4DC \uD488\uC9C8, \uBAA8\uBC94 \uC0AC\uB840, \uC7A0\uC7AC\uC801 \uBC84\uADF8\uC5D0 \uC9D1\uC911\uD558\uC138\uC694.",
    "settings.agentBehaviour.createMode.prompt.help": "\uC774 \uBAA8\uB4DC\uB97C \uC0AC\uC6A9\uD560 \uB54C AI \uC5D0\uC774\uC804\uD2B8\uC5D0 \uB300\uD55C \uC9C0\uCE68.",
    "settings.agentBehaviour.createMode.button": "\uB9CC\uB4E4\uAE30",
    "settings.agentBehaviour.createMode.cancel": "\uCDE8\uC18C",
    "settings.agentBehaviour.createMode.nameRequired": "\uC774\uB984\uC740 \uD544\uC218\uC785\uB2C8\uB2E4",
    "settings.agentBehaviour.createMode.nameInvalid": "\uC774\uB984\uC5D0\uB294 \uC18C\uBB38\uC790, \uC22B\uC790, \uD558\uC774\uD508\uB9CC \uD3EC\uD568\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
    "settings.agentBehaviour.createMode.nameTaken": "\uC774 \uC774\uB984\uC758 \uBAA8\uB4DC\uAC00 \uC774\uBBF8 \uC874\uC7AC\uD569\uB2C8\uB2E4",
    "settings.agentBehaviour.importMode": "\uAC00\uC838\uC624\uAE30",
    "settings.agentBehaviour.importMode.invalidName": "\uD30C\uC77C\uC758 \uBAA8\uB4DC \uC774\uB984\uC774 \uC798\uBABB\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC774\uB984\uC740 \uC18C\uBB38\uC790\uB85C \uC2DC\uC791\uD558\uACE0 \uC18C\uBB38\uC790, \uC22B\uC790, \uD558\uC774\uD508\uB9CC \uD3EC\uD568\uD574\uC57C \uD569\uB2C8\uB2E4.",
    "settings.agentBehaviour.importMode.nameTaken": "\uC774 \uC774\uB984\uC758 \uBAA8\uB4DC\uAC00 \uC774\uBBF8 \uC874\uC7AC\uD569\uB2C8\uB2E4.",
    "settings.agentBehaviour.importMode.invalidJson": "\uC798\uBABB\uB41C JSON \uD30C\uC77C\uC785\uB2C8\uB2E4. \uC720\uD6A8\uD55C \uC5D0\uC774\uC804\uD2B8 \uC815\uC758 \uD30C\uC77C\uC744 \uC120\uD0DD\uD558\uC138\uC694.",
    "settings.agentBehaviour.importMode.tooLarge": "\uD30C\uC77C\uC774 \uB108\uBB34 \uD07D\uB2C8\uB2E4. \uC5D0\uC774\uC804\uD2B8 \uC815\uC758\uB294 1 MB \uBBF8\uB9CC\uC774\uC5B4\uC57C \uD569\uB2C8\uB2E4.",
    "settings.agentBehaviour.exportMode": "\uC5D0\uC774\uC804\uD2B8 \uC815\uC758 \uB0B4\uBCF4\uB0B4\uAE30",
    "settings.agentBehaviour.editMode": "\uBAA8\uB4DC \uD3B8\uC9D1",
    "settings.agentBehaviour.editMode.description": "\uC124\uBA85",
    "settings.agentBehaviour.editMode.prompt": "\uC2DC\uC2A4\uD15C \uD504\uB86C\uD504\uD2B8",
    "settings.agentBehaviour.editMode.save": "\uC644\uB8CC",
    "settings.agentBehaviour.editMode.back": "\uBAA9\uB85D\uC73C\uB85C \uB3CC\uC544\uAC00\uAE30",
    "settings.agentBehaviour.editMode.native": "\uC774\uAC83\uC740 \uB0B4\uC7A5 \uBAA8\uB4DC\uC785\uB2C8\uB2E4. \uAE30\uBCF8 \uC815\uC758\uB294 \uBCC0\uACBD\uD560 \uC218 \uC5C6\uC9C0\uB9CC, \uC544\uB798\uC5D0\uC11C \uC7AC\uC815\uC758\uB97C \uAD6C\uC131\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "settings.agentBehaviour.editMode.promptOverride": "\uC774 \uB0B4\uC7A5 \uBAA8\uB4DC\uC5D0 \uB300\uD55C \uC0AC\uC6A9\uC790 \uC9C0\uC815 \uD504\uB86C\uD504\uD2B8 \uC7AC\uC815\uC758",
