    "settings.agentBehaviour.skillUrls": "\uC2A4\uD0AC URL",
    "settings.agentBehaviour.removeSkill.title": "\uC2A4\uD0AC \uC81C\uAC70",
    "settings.agentBehaviour.removeSkill.confirm": '\uC2A4\uD0AC "{{name}}"\uC744(\uB97C) \uC81C\uAC70\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C? \uB514\uC2A4\uD06C\uC5D0\uC11C \uC2A4\uD0AC \uD30C\uC77C\uC774 \uC0AD\uC81C\uB429\uB2C8\uB2E4.',
    "settings.agentBehaviour.removeSkill.button": "\uC81C\uAC70",
    "settings.agentBehaviour.rules.description": "\uADDC\uCE59\uC740 \uC5D0\uC774\uC804\uD2B8 \uB3D9\uC791\uC744 \uC548\uB0B4\uD558\uB294 \uC9C0\uC2DC \uD30C\uC77C\uC785\uB2C8\uB2E4. \uBAA8\uB4E0 \uB300\uD654\uC758 \uC2DC\uC2A4\uD15C \uD504\uB86C\uD504\uD2B8\uC5D0 \uD3EC\uD568\uB429\uB2C8\uB2E4. \uCD94\uAC00 \uADDC\uCE59\uC744 \uD3EC\uD568\uD558\uB824\uBA74 \uC544\uB798\uC5D0 \uD30C\uC77C \uACBD\uB85C\uB97C \uCD94\uAC00\uD558\uC138\uC694.",
    "settings.agentBehaviour.instructionFiles": "\uCD94\uAC00 \uC9C0\uC2DC \uD30C\uC77C",
    "settings.agentBehaviour.instructionFiles.description": "\uC2DC\uC2A4\uD15C \uD504\uB86C\uD504\uD2B8\uC5D0 \uD3EC\uD568\uB418\uB294 \uCD94\uAC00 \uC9C0\uC2DC \uD30C\uC77C \uACBD\uB85C",
    "settings.agentBehaviour.claudeCompat.heading": "Claude Code \uD638\uD658\uC131",
    "settings.agentBehaviour.claudeCompat.title": "Claude Code \uD30C\uC77C \uB85C\uB4DC",
    "settings.agentBehaviour.claudeCompat.description": "Claude Code \uC124\uC815 \uB514\uB809\uD130\uB9AC\uC5D0\uC11C \uC138\uC158\uC73C\uB85C CLAUDE.md \uC9C0\uCE68 \uBC0F \uC2A4\uD0AC\uC744 \uB85C\uB4DC\uD569\uB2C8\uB2E4. Kilo\uAC00 Claude Code \uC9C0\uCE68 \uBC0F \uC2A4\uD0AC\uC744 \uC0AC\uC6A9\uD558\uAC8C \uD558\uB824\uBA74 \uD65C\uC131\uD654\uD558\uC138\uC694. \uB2E4\uC2DC \uC2DC\uC791\uD574\uC57C \uD569\uB2C8\uB2E4.",
    "settings.agentBehaviour.mcpDetail.command": "\uBA85\uB839\uC5B4",
    "settings.agentBehaviour.mcpDetail.args": "\uC778\uC218",
    "settings.agentBehaviour.mcpDetail.env": "\uD658\uACBD",
    "settings.agentBehaviour.mcpDetail.disabled": "\uC774 \uC11C\uBC84\uB294 \uBE44\uD65C\uC131\uD654\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.",
    "settings.agentBehaviour.mcpBrowseMarketplace": "\uB9C8\uCF13\uD50C\uB808\uC774\uC2A4 \uB458\uB7EC\uBCF4\uAE30",
    "settings.agentBehaviour.mcpEmpty": "MCP \uC11C\uBC84\uAC00 \uAD6C\uC131\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. kilo.jsonc\uC5D0\uC11C MCP \uC11C\uBC84\uB97C \uCD94\uAC00\uD558\uAC70\uB098 \uC5D0\uC774\uC804\uD2B8\uC5D0\uAC8C \uCD94\uAC00\uB97C \uC694\uCCAD\uD558\uC138\uC694.",
    "settings.agentBehaviour.workflowsPlaceholder": "\uC6CC\uD06C\uD50C\uB85C\uC6B0\uB294 \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uC758 \uC6CC\uD06C\uD50C\uB85C\uC6B0 \uD30C\uC77C\uC744 \uD1B5\uD574 \uAD00\uB9AC\uB429\uB2C8\uB2E4.",
    "settings.agentBehaviour.workflows.description": "\uC6CC\uD06C\uD50C\uB85C\uC6B0\uB294 \uAD6C\uC131\uC5D0\uC11C \uC815\uC758\uB41C \uC0AC\uC6A9\uC790 \uC815\uC758 \uC2AC\uB798\uC2DC \uBA85\uB839\uC785\uB2C8\uB2E4. \uCC44\uD305\uC5D0\uC11C /command-name\uC744 \uC785\uB825\uD558\uC5EC \uC2E4\uD589\uD569\uB2C8\uB2E4. \uBA85\uB839\uC740 opencode.json\uC758 'command' \uC139\uC158\uC5D0\uC11C \uAD6C\uC131\uB429\uB2C8\uB2E4.",
    "settings.agentBehaviour.workflows.empty": "\uAD6C\uC131\uB41C \uC0AC\uC6A9\uC790 \uC815\uC758 \uBA85\uB839\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. opencode.json\uC5D0 \uBA85\uB839\uC744 \uCD94\uAC00\uD558\uBA74 \uC5EC\uAE30\uC5D0 \uD45C\uC2DC\uB429\uB2C8\uB2E4.",
