    "prompt.action.autoApprove.enable": "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0430\u0432\u0442\u043E\u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435",
    "prompt.action.autoApprove.disable": "\u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0430\u0432\u0442\u043E\u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435",
    "prompt.action.autoApprove.enabled": "\u0410\u0432\u0442\u043E\u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E. \u0417\u0430\u043F\u0440\u043E\u0441\u044B \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0439 \u0431\u0443\u0434\u0443\u0442 \u043E\u0434\u043E\u0431\u0440\u044F\u0442\u044C\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
    "prompt.action.autoApprove.disabled": "\u0410\u0432\u0442\u043E\u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E. \u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043E\u0434\u043E\u0431\u0440\u044F\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441\u044B \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0439.",
    "prompt.action.resetModel": "\u0421\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043C\u043E\u0434\u0435\u043B\u044C \u043D\u0430 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E",
    "prompt.action.indexing": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0438\u0438",
    "prompt.action.enhanceDescription": "\u041A\u043D\u043E\u043F\u043A\u0430 '\u0423\u043B\u0443\u0447\u0448\u0438\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441' \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0432\u0430\u0448 \u0437\u0430\u043F\u0440\u043E\u0441 \u043B\u0443\u0447\u0448\u0435, \u043F\u0440\u0435\u0434\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044F \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442, \u0443\u0442\u043E\u0447\u043D\u0435\u043D\u0438\u044F \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0444\u043E\u0440\u043C\u0443\u043B\u0438\u0440\u043E\u0432\u043A\u0443. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0432\u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u043F\u0440\u043E\u0441 \u0438 \u0441\u043D\u043E\u0432\u0430 \u043D\u0430\u0436\u0430\u0442\u044C \u043A\u043D\u043E\u043F\u043A\u0443, \u0447\u0442\u043E\u0431\u044B \u0443\u0432\u0438\u0434\u0435\u0442\u044C, \u043A\u0430\u043A \u044D\u0442\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
    "prompt.action.sandbox.enable": "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0443",
    "prompt.action.sandbox.disable": "\u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0443",
    "prompt.action.sandbox.enabled": "\u041F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0430 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0430. \u041A\u043E\u043C\u0430\u043D\u0434\u044B \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438 \u0430\u0433\u0435\u043D\u0442\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u044B \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430\u043C\u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0438 Kilo.",
    "prompt.action.sandbox.disabled": "\u041F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430. \u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0442\u044C \u0437\u0430\u043F\u0438\u0441\u044C \u043A\u043E\u043C\u0430\u043D\u0434 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438 \u0430\u0433\u0435\u043D\u0442\u0430 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430\u043C\u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0438 Kilo.",
    "prompt.action.sandbox.status.enabled": "\u041F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0430 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0430",
    "prompt.action.sandbox.status.disabled": "\u041F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430",
