    "speechToText.tooltip.stop": "\u041E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0432\u0443\u043A\u0430",
