    "settings.agentBehaviour.noSkillsFound": "\u041D\u0430\u0432\u044B\u043A\u0438 \u043D\u0435 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D\u044B. \u0414\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u043F\u0443\u0442\u0438 \u043A \u043F\u0430\u043F\u043A\u0430\u043C \u043D\u0430\u0432\u044B\u043A\u043E\u0432 \u0438\u043B\u0438 URL-\u0430\u0434\u0440\u0435\u0441\u0430 \u043D\u0438\u0436\u0435, \u0447\u0442\u043E\u0431\u044B \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043D\u0430\u0432\u044B\u043A\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u043C\u0438.",
    "settings.agentBehaviour.availableModes": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0435 \u0440\u0435\u0436\u0438\u043C\u044B",
