    "prompt.action.autoApprove.disabled": "\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A\u0629 \u0645\u0639\u0637\u0644\u0629. \u0627\u0646\u0642\u0631 \u0644\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0644\u0649 \u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0623\u0630\u0648\u0646\u0627\u062A \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B.",
