    "prompt.action.enhanceDescription": "\u0632\u0631 \xAB\u062D\u0633\u0651\u0646 \u0627\u0644\u0645\u0648\u062C\u0647\xBB \u064A\u0637\u0648\u0651\u0631 \u0645\u0648\u062C\u0647\u0643 \u0628\u0625\u0636\u0627\u0641\u0629 \u0633\u064A\u0627\u0642 \u0623\u0648 \u062A\u0648\u0636\u064A\u062D \u0623\u0648 \u0625\u0639\u0627\u062F\u0629 \u0635\u064A\u0627\u063A\u0629. \u062C\u0631\u0651\u0628 \u0627\u0643\u062A\u0628 \u0645\u0648\u062C\u0647 \u0647\u0646\u0627 \u062B\u0645 \u0627\u0636\u063A\u0637 \u0627\u0644\u0632\u0631 \u0645\u0631\u0629 \u062B\u0627\u0646\u064A\u0629 \u0648\u0634\u0648\u0641 \u0627\u0644\u0646\u062A\u064A\u062C\u0629.",
