    "settings.providers.betaNotice": "\u062D\u0627\u0644\u064A\u0627\u064B\u060C \u064A\u0645\u0643\u0646 \u0625\u0639\u062F\u0627\u062F \u0645\u0632\u0648\u062F Kilo Gateway \u0641\u0642\u0637 \u0641\u064A \u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A. \u0633\u064A\u062A\u0648\u0641\u0631 \u062F\u0639\u0645 \u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0645\u0632\u0648\u062F\u064A\u0646 \u0627\u0644\u0622\u062E\u0631\u064A\u0646 \u0642\u0631\u064A\u0628\u0627\u064B \u062E\u0644\u0627\u0644 \u0627\u0644\u0641\u062A\u0631\u0629 \u0627\u0644\u062A\u062C\u0631\u064A\u0628\u064A\u0629. \u0641\u064A \u063A\u0636\u0648\u0646 \u0630\u0644\u0643\u060C \u064A\u0645\u0643\u0646\u0643 \u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0645\u0632\u0648\u062F\u064A\u0646 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 CLI \u0623\u0648 \u0645\u0644\u0641 \u0627\u0644\u062A\u0643\u0648\u064A\u0646. \u0646\u062D\u0646 \u0645\u0644\u062A\u0632\u0645\u0648\u0646 \u0628\u0625\u0628\u0642\u0627\u0621 Kilo \u0645\u0641\u062A\u0648\u062D\u0627\u064B\u060C \u062F\u0648\u0646 \u062A\u0642\u064A\u064A\u062F.",
    "settings.providers.section.connected": "\u0627\u0644\u0645\u0648\u0641\u0631\u0648\u0646 \u0627\u0644\u0645\u062A\u0635\u0644\u0648\u0646",
