    "settings.providers.modeModels": "\u0646\u0645\u0648\u0630\u062C \u0644\u0643\u0644 \u0648\u0636\u0639",
    "settings.providers.custom.note": "\u0623\u0636\u0641 \u0645\u0632\u0648\u062F\u064B\u0627 \u0645\u062E\u0635\u0635\u064B\u0627 \u0639\u0628\u0631 \u0639\u0646\u0648\u0627\u0646 URL \u0627\u0644\u0623\u0633\u0627\u0633\u064A.",
