    "settings.aboutKiloCode.support.prefix": "\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0641\u0648\u062A\u0631\u0629 \u0623\u0648 \u0627\u0644\u062D\u0633\u0627\u0628\u060C \u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u062F\u0639\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0639\u0644\u0649",
