    "settings.context.memory.autoSave.title": "\u062D\u0641\u0638 \u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627",
    "settings.context.memory.autoSave.description": "\u062D\u0641\u0638 \u062D\u0642\u0627\u0626\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u062F\u0627\u0626\u0645\u0629 \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627 \u0645\u0646 \u0627\u0644\u062C\u0648\u0644\u0627\u062A \u0627\u0644\u0645\u0643\u062A\u0645\u0644\u0629 \u0639\u0646\u062F \u062A\u0641\u0639\u064A\u0644 \u0627\u0644\u0630\u0627\u0643\u0631\u0629.",
