    "settings.commitMessage.title": "Commit Message",
    "settings.commitMessage.override.title": "\u0627\u0633\u062A\u062E\u062F\u0627\u0645 prompt \u0645\u062E\u0635\u0635",
    "settings.commitMessage.override.description": "\u062A\u062C\u0627\u0648\u0632 prompt \u0627\u0644\u0640 commit message \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A. \u0639\u0646\u062F \u0627\u0644\u062A\u0641\u0639\u064A\u0644\u060C \u0633\u064A\u0633\u062A\u0628\u062F\u0644 \u0627\u0644\u0640 prompt \u0627\u0644\u0645\u062E\u0635\u0635 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643 \u0627\u0644\u0640 prompt \u0627\u0644\u0645\u062F\u0645\u062C \u0644\u0640 conventional commits \u0628\u0627\u0644\u0643\u0627\u0645\u0644.",
    "settings.commitMessage.prompt.title": "prompt \u0645\u062E\u0635\u0635",
    "settings.commitMessage.prompt.description": "\u0627\u0644\u0640 prompt \u0627\u0644\u0646\u0638\u0627\u0645\u064A \u0627\u0644\u0645\u0631\u0633\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0639\u0646\u062F \u0625\u0646\u0634\u0627\u0621 commit messages. \u0647\u0630\u0627 \u064A\u0633\u062A\u0628\u062F\u0644 \u0627\u0644\u0640 prompt \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0628\u0627\u0644\u0643\u0627\u0645\u0644.",
    "settings.commitMessage.prompt.placeholder": "\u0639\u0644\u0649 \u0633\u0628\u064A\u0644 \u0627\u0644\u0645\u062B\u0627\u0644: \u0642\u0645 \u0628\u0625\u0646\u0634\u0627\u0621 commit messages \u0628\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0628\u0627\u062A\u0628\u0627\u0639 \u062A\u0646\u0633\u064A\u0642 conventional commits. \u0623\u0631\u062C\u0639 \u0627\u0644\u0640 commit message \u0641\u0642\u0637.",
    "settings.commitMessage.language.sync": "\u0645\u0632\u0627\u0645\u0646\u0629 \u0645\u0639 \u0644\u063A\u0629 \u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645",
    "settings.commitMessage.language.title": "\u0627\u0644\u0644\u063A\u0629",
    "settings.commitMessage.language.description": "\u0627\u062E\u062A\u0631 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0627\u0644\u062A\u0632\u0627\u0645 \u0627\u0644\u062A\u064A \u062A\u0648\u0644\u062F\u0647\u0627 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A:",
    "settings.display.username.title": "\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645",
    "settings.display.username.description": "\u0627\u0633\u0645 \u0645\u0633\u062A\u062E\u062F\u0645 \u0645\u062E\u0635\u0635 \u0641\u064A \u0627\u0644\u0645\u062D\u0627\u062F\u062B\u0627\u062A",
    "settings.display.fontSize.title": "\u062D\u062C\u0645 \u0627\u0644\u062E\u0637",
    "settings.display.fontSize.description": "\u0627\u0636\u0628\u0637 \u062D\u062C\u0645 \u062E\u0637 webview UI \u0627\u0644\u062E\u0627\u0635 \u0628\u0640 Kilo \u0628\u0634\u0643\u0644 \u0645\u0633\u062A\u0642\u0644 \u0639\u0646 VS Code.",
    "settings.display.reasoningAutoCollapse.title": "\u0637\u064A \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627",
    "settings.display.reasoningAutoCollapse.description": "\u064A\u0637\u0648\u064A \u0643\u062A\u0644 \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0628\u0639\u062F \u0623\u0646 \u064A\u0646\u062A\u0647\u064A \u0627\u0644\u0648\u0643\u064A\u0644 \u0645\u0646 \u0643\u062A\u0627\u0628\u062A\u0647\u0627. \u0627\u062A\u0631\u0643\u0647 \u0645\u0639\u0637\u0644\u0627\u064B \u0644\u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0645\u0648\u0633\u0639\u064B\u0627 \u0645\u0627 \u0644\u0645 \u062A\u0637\u0648\u0647 \u064A\u062F\u0648\u064A\u064B\u0627.",
    "settings.display.shiftTabCycle.title": "\u062A\u0628\u062F\u064A\u0644 \u062C\u0647\u062F \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 Shift+Tab",
    "settings.display.shiftTabCycle.description": "\u0627\u0636\u063A\u0637 \u0639\u0644\u0649 Shift+Tab \u0641\u064A \u062D\u0642\u0644 \u0625\u062F\u062E\u0627\u0644 \u0627\u0644\u0645\u0648\u062C\u0647 \u0644\u0644\u062A\u0628\u062F\u064A\u0644 \u0625\u0644\u0649 \u0645\u0633\u062A\u0648\u0649 \u062C\u0647\u062F \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0627\u0644\u062A\u0627\u0644\u064A. \u0639\u0637\u0651\u0644 \u0647\u0630\u0627 \u0627\u0644\u062E\u064A\u0627\u0631 \u0644\u0644\u0627\u062D\u062A\u0641\u0627\u0638 \u0628\u0640 Shift+Tab \u0644\u0644\u062A\u0646\u0642\u0644 \u0628\u064A\u0646 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062A\u0631\u0643\u064A\u0632 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D.",
