    "settings.display.fontSize.title": "\u0E02\u0E19\u0E32\u0E14\u0E1F\u0E2D\u0E19\u0E15\u0E4C",
    "settings.display.fontSize.description": "\u0E1B\u0E23\u0E31\u0E1A\u0E02\u0E19\u0E32\u0E14\u0E1F\u0E2D\u0E19\u0E15\u0E4C webview UI \u0E02\u0E2D\u0E07 Kilo \u0E41\u0E22\u0E01\u0E40\u0E1B\u0E47\u0E19\u0E2D\u0E34\u0E2A\u0E23\u0E30\u0E08\u0E32\u0E01 VS Code.",
    "settings.display.reasoningAutoCollapse.title": "\u0E22\u0E38\u0E1A\u0E40\u0E2B\u0E15\u0E38\u0E1C\u0E25\u0E2D\u0E31\u0E15\u0E42\u0E19\u0E21\u0E31\u0E15\u0E34",
