    "provider.anaconda.state.unsupported": "Anaconda Desktop \u043D\u0435 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u0443\u0454\u0442\u044C\u0441\u044F \u043D\u0430 {{platform}}.",
    "provider.anaconda.state.notInstalled": "\u0412\u0441\u0442\u0430\u043D\u043E\u0432\u0456\u0442\u044C Anaconda Desktop \u043D\u0430 \u0446\u044C\u043E\u043C\u0443 \u043A\u043E\u043C\u043F'\u044E\u0442\u0435\u0440\u0456, \u0430 \u043F\u043E\u0442\u0456\u043C \u043F\u043E\u0432\u0435\u0440\u043D\u0456\u0442\u044C\u0441\u044F \u0441\u044E\u0434\u0438. Kilo \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0454 \u0456\u043D\u0441\u0442\u0430\u043B\u044F\u0442\u043E\u0440 \u0437\u0430 \u0432\u0430\u0441.",
    "provider.anaconda.state.notRunning": "\u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 Anaconda Desktop, \u0437\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044C \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0442\u0430 \u0443\u0432\u0456\u0439\u0434\u0456\u0442\u044C, \u043F\u043E\u0442\u0456\u043C \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \xAB\u041F\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0449\u0435 \u0440\u0430\u0437\xBB.",
    "provider.anaconda.state.invalidConfig": "\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F Anaconda Desktop \u043D\u0435\u043F\u043E\u0432\u043D\u0435. \u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 Desktop, \u0437\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044C \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0442\u0430 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0439\u043E\u0433\u043E \u0437\u0430 \u043F\u043E\u0442\u0440\u0435\u0431\u0438.",
    "provider.anaconda.state.signedOut": "\u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 Anaconda Desktop \u0442\u0430 \u0443\u0432\u0456\u0439\u0434\u0456\u0442\u044C \u043F\u0435\u0440\u0435\u0434 \u043F\u0456\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044F\u043C Kilo.",
    "provider.anaconda.state.unauthorized": "Kilo \u043D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F \u043E\u0442\u0440\u0438\u043C\u0430\u0442\u0438 \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u043E Anaconda Desktop. \u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 Desktop, \u0443\u0432\u0456\u0439\u0434\u0456\u0442\u044C \u0437\u043D\u043E\u0432\u0443 \u0442\u0430 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0439\u043E\u0433\u043E \u0437\u0430 \u043F\u043E\u0442\u0440\u0435\u0431\u0438.",
    "provider.anaconda.state.unavailable": "Anaconda Desktop \u0449\u0435 \u043D\u0435 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u0430\u0454. \u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 \u0439\u043E\u0433\u043E \u0442\u0430 \u0437\u0430\u0447\u0435\u043A\u0430\u0439\u0442\u0435, \u0434\u043E\u043A\u0438 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0437\u0430\u043F\u0443\u0441\u043A.",
    "provider.anaconda.state.noModel": "\u0412 Anaconda Desktop \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0442\u0435 \u043C\u043E\u0434\u0435\u043B\u044C \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0456\u0457 \u0442\u0435\u043A\u0441\u0442\u0443. \u0417\u0430 \u043C\u043E\u0436\u043B\u0438\u0432\u043E\u0441\u0442\u0456 \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u043C\u043E\u0434\u0435\u043B\u044C \u0456\u0437 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u043A\u043E\u044E \u0432\u0438\u043A\u043B\u0438\u043A\u0443 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0456\u0432, \u043F\u043E\u0442\u0456\u043C \u0437\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0457\u0457 \u0441\u0435\u0440\u0432\u0435\u0440.",
    "provider.anaconda.state.noServer_one": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u0430 1 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0456\u0457 \u0442\u0435\u043A\u0441\u0442\u0443. \u0417\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 \u043C\u043E\u0434\u0435\u043B\u0456 \u0432 Anaconda Desktop. \u041D\u0430\u043F\u043E\u043B\u0435\u0433\u043B\u0438\u0432\u043E \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0454\u043C\u043E \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u043C\u043E\u0434\u0435\u043B\u0456 \u0437 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u043A\u043E\u044E \u0432\u0438\u043A\u043B\u0438\u043A\u0443 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0456\u0432.",
    "provider.anaconda.state.noServer_other": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u0438\u0445 \u043C\u043E\u0434\u0435\u043B\u0435\u0439 \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0456\u0457 \u0442\u0435\u043A\u0441\u0442\u0443: {{count}}. \u0417\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 \u043C\u043E\u0434\u0435\u043B\u0456 \u0432 Anaconda Desktop. \u041D\u0430\u043F\u043E\u043B\u0435\u0433\u043B\u0438\u0432\u043E \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0454\u043C\u043E \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u043C\u043E\u0434\u0435\u043B\u0456 \u0437 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u043A\u043E\u044E \u0432\u0438\u043A\u043B\u0438\u043A\u0443 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0456\u0432.",
    "provider.anaconda.state.unhealthy": "\u0410\u043A\u0442\u0438\u0432\u043D\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 \u0456\u043D\u0444\u0435\u0440\u0435\u043D\u0441\u0443 \u0449\u0435 \u043D\u0435 \u0441\u043F\u0440\u0430\u0432\u043D\u0438\u0439. \u041F\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0439\u043E\u0433\u043E \u0432 Anaconda Desktop \u0442\u0430 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 \u0437\u0430 \u043F\u043E\u0442\u0440\u0435\u0431\u0438.",
    "provider.anaconda.state.ready": "Kilo \u0437\u043D\u0430\u0439\u0448\u043E\u0432 \u0441\u043F\u0440\u0430\u0432\u043D\u0438\u0439 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0456\u0457 \u0442\u0435\u043A\u0441\u0442\u0443 \u0442\u0430 \u043C\u043E\u0436\u0435 \u0456\u043C\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0439\u043E\u0433\u043E \u043F\u043E\u0442\u043E\u0447\u043D\u0456 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043F\u0456\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044F.",
