    "settings.aboutKiloCode.support.prefix": "\u0417 \u043F\u0438\u0442\u0430\u043D\u044C \u0432\u0438\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u044F \u0440\u0430\u0445\u0443\u043D\u043A\u0456\u0432 \u0430\u0431\u043E \u0430\u043A\u0430\u0443\u043D\u0442\u0443 \u0437\u0432\u0435\u0440\u043D\u0456\u0442\u044C\u0441\u044F \u0434\u043E \u0441\u043B\u0443\u0436\u0431\u0438 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u043A\u0438:",
    "settings.aboutKiloCode.resetSettings.title": "\u0421\u043A\u0438\u0434\u0430\u043D\u043D\u044F \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C",
    "settings.aboutKiloCode.resetSettings.description": "\u0426\u0435 \u0441\u043A\u0438\u043D\u0435 \u043B\u0438\u0448\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F, \u0441\u043F\u0435\u0446\u0438\u0444\u0456\u0447\u043D\u0456 \u0434\u043B\u044F \u0440\u043E\u0437\u0448\u0438\u0440\u0435\u043D\u043D\u044F VS Code, \u0434\u043E \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0438\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u044C. \u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F, \u0449\u043E \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044E\u0442\u044C\u0441\u044F \u0432 \u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0457 CLI (\u0442\u0430\u043A\u0456 \u044F\u043A \u0440\u0435\u0436\u0438\u043C\u0438 \u0442\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E\u0433\u043E \u0441\u0445\u0432\u0430\u043B\u0435\u043D\u043D\u044F), \u043D\u0435 \u0431\u0443\u0434\u0443\u0442\u044C \u0441\u043A\u0438\u043D\u0443\u0442\u0456.",
    "settings.aboutKiloCode.resetSettings.button": "\u0421\u043A\u0438\u043D\u0443\u0442\u0438 \u0432\u0441\u0456 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F",
    "settings.aboutKiloCode.resetSettings.notificationsButton": "Reset Read Notifications",
    "settings.aboutKiloCode.settingsTransfer.title": "\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u043D\u044F \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C",
    "settings.aboutKiloCode.settingsTransfer.description": "\u0415\u043A\u0441\u043F\u043E\u0440\u0442\u0443\u0439\u0442\u0435 \u0430\u0431\u043E \u0456\u043C\u043F\u043E\u0440\u0442\u0443\u0439\u0442\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u043D\u044F \u043C\u0456\u0436 \u0435\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u0430\u043C\u0438 VS Code.",
    "settings.aboutKiloCode.exportSettings": "\u0415\u043A\u0441\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438",
    "settings.aboutKiloCode.importSettings": "\u0406\u043C\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438",
    "settings.aboutKiloCode.importSettings.invalidJson": "\u041D\u0435\u0434\u0456\u0439\u0441\u043D\u0438\u0439 \u0444\u0430\u0439\u043B JSON. \u0411\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u0434\u0456\u0439\u0441\u043D\u0438\u0439 \u0444\u0430\u0439\u043B \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C.",
    "settings.aboutKiloCode.importSettings.invalidConfig": "\u0424\u0430\u0439\u043B \u043D\u0435 \u043C\u0456\u0441\u0442\u0438\u0442\u044C \u0434\u0456\u0439\u0441\u043D\u0438\u0445 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C Kilo.",
    "settings.aboutKiloCode.importSettings.tooLarge": "\u0424\u0430\u0439\u043B \u0437\u0430\u043D\u0430\u0434\u0442\u043E \u0432\u0435\u043B\u0438\u043A\u0438\u0439. \u0424\u0430\u0439\u043B\u0438 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C \u043C\u0430\u044E\u0442\u044C \u0431\u0443\u0442\u0438 \u043C\u0435\u043D\u0448\u0435 1 \u041C\u0411.",
    "settings.aboutKiloCode.importSettings.newerVersion": "\u0426\u0435\u0439 \u0444\u0430\u0439\u043B \u0431\u0443\u043B\u043E \u0435\u043A\u0441\u043F\u043E\u0440\u0442\u043E\u0432\u0430\u043D\u043E \u0437 \u043D\u043E\u0432\u0456\u0448\u043E\u0457 \u0432\u0435\u0440\u0441\u0456\u0457 Kilo. \u0414\u0435\u044F\u043A\u0456 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043C\u043E\u0436\u0443\u0442\u044C \u0431\u0443\u0442\u0438 \u043F\u0440\u043E\u0456\u0433\u043D\u043E\u0440\u043E\u0432\u0430\u043D\u0456.",
    "settings.aboutKiloCode.importSettings.success": "\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0456\u043C\u043F\u043E\u0440\u0442\u043E\u0432\u0430\u043D\u043E. \u041F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u044C\u0442\u0435 \u0437\u043C\u0456\u043D\u0438 \u0432\u0438\u0449\u0435, \u043F\u043E\u0442\u0456\u043C \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C \u0417\u0431\u0435\u0440\u0435\u0433\u0442\u0438.",
    "settings.aboutKiloCode.telemetry.title": "\u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u044F",
    "settings.aboutKiloCode.telemetry.description": '\u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u044F \u043A\u0435\u0440\u0443\u0454\u0442\u044C\u0441\u044F \u0432\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u0438\u043C \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F\u043C \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u0457 VS Code. \u0429\u043E\u0431 \u0432\u0438\u043C\u043A\u043D\u0443\u0442\u0438 \u0457\u0457, \u043F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0434\u043E \u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F > \u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u044F > \u0420\u0456\u0432\u0435\u043D\u044C \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u0457 \u0442\u0430 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u0456\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F "off". \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0456\u0442\u044C VS Code, \u0449\u043E\u0431 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u0432\u0430\u0442\u0438 \u0437\u043C\u0456\u043D\u0443.',
    "settings.aboutKiloCode.telemetry.openSettings": "\u0412\u0456\u0434\u043A\u0440\u0438\u0442\u0438 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0456\u0457",
