    "settings.agentBehaviour.editMcp.transportLocal": "\u041B\u043E\u043A\u0430\u043B\u044C\u043D\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 (stdio \u0442\u0440\u0430\u043D\u0441\u043F\u043E\u0440\u0442)",
    "settings.agentBehaviour.editMcp.transportRemote": "\u0412\u0456\u0434\u0434\u0430\u043B\u0435\u043D\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 (SSE/HTTP \u0442\u0440\u0430\u043D\u0441\u043F\u043E\u0440\u0442)",
