    "settings.providers.defaultModel.title": "\u041C\u043E\u0434\u0435\u043B\u044C \u0437\u0430 \u0437\u0430\u043C\u043E\u0432\u0447\u0443\u0432\u0430\u043D\u043D\u044F\u043C",
    "settings.providers.defaultModel.description": "\u041E\u0441\u043D\u043E\u0432\u043D\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u0447\u0430\u0442\u0456\u0432",
    "settings.providers.smallModel.title": "\u041C\u0430\u043B\u0430 \u043C\u043E\u0434\u0435\u043B\u044C",
    "settings.providers.smallModel.description": "\u041B\u0435\u0433\u043A\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0456\u0457 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0456\u0432, \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u044C \u043A\u043E\u043C\u0456\u0442\u0456\u0432, \u043F\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u043D\u044F \u0437\u0430\u043F\u0438\u0442\u0456\u0432 \u0442\u0430 \u0456\u043D\u0448\u0438\u0445 \u0448\u0432\u0438\u0434\u043A\u0438\u0445 \u0437\u0430\u0432\u0434\u0430\u043D\u044C",
    "settings.providers.subagentModel.title": "\u041C\u043E\u0434\u0435\u043B\u044C \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u0430",
    "settings.providers.subagentModel.description": "\u041C\u043E\u0434\u0435\u043B\u044C \u0437\u0430 \u0437\u0430\u043C\u043E\u0432\u0447\u0443\u0432\u0430\u043D\u043D\u044F\u043C \u0442\u0430 \u0440\u0456\u0432\u0435\u043D\u044C \u043C\u0456\u0440\u043A\u0443\u0432\u0430\u043D\u043D\u044F \u0434\u043B\u044F \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u0456\u0432 task-tool. \u0417\u0430\u043B\u0438\u0448\u0442\u0435 \u043F\u043E\u0440\u043E\u0436\u043D\u0456\u043C, \u0449\u043E\u0431 \u0443\u0441\u043F\u0430\u0434\u043A\u0443\u0432\u0430\u0442\u0438 \u043C\u043E\u0434\u0435\u043B\u044C \u0430\u0433\u0435\u043D\u0442\u0430, \u0449\u043E \u0432\u0438\u043A\u043B\u0438\u043A\u0430\u0454.",
    "settings.models.hidePromptTraining.title": "\u041F\u0440\u0438\u0445\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u043C\u043E\u0434\u0435\u043B\u0456, \u0449\u043E \u043D\u0430\u0432\u0447\u0430\u044E\u0442\u044C\u0441\u044F \u043D\u0430 \u0437\u0430\u043F\u0438\u0442\u0430\u0445",
    "settings.models.hidePromptTraining.description": "\u041F\u0440\u0438\u0445\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u043C\u043E\u0434\u0435\u043B\u0456 Kilo Gateway, \u043F\u043E\u0441\u0442\u0430\u0447\u0430\u043B\u044C\u043D\u0438\u043A\u0438 \u044F\u043A\u0438\u0445 \u043C\u043E\u0436\u0443\u0442\u044C \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u0432\u0430\u0448\u0456 \u0437\u0430\u043F\u0438\u0442\u0438 \u0434\u043B\u044F \u043D\u0430\u0432\u0447\u0430\u043D\u043D\u044F.",
    "settings.providers.modeModels": "\u041C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0443",
    "settings.providers.modeModels.description": "\u041F\u0435\u0440\u0435\u0432\u0438\u0437\u043D\u0430\u0447\u0438\u0442\u0438 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0443 \u043C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u043F\u0435\u0432\u043D\u0438\u0445 \u0440\u0435\u0436\u0438\u043C\u0456\u0432. \u042F\u043A\u0449\u043E \u043D\u0435 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E, \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454\u0442\u044C\u0441\u044F \u0437\u0430\u0433\u0430\u043B\u044C\u043D\u0430 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0430 \u043C\u043E\u0434\u0435\u043B\u044C.",
    "settings.providers.disabled": "\u0412\u0438\u043C\u043A\u043D\u0435\u043D\u0456 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0438",
    "settings.providers.disabled.description": "\u041F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0438, \u0449\u043E \u0431\u0443\u0434\u0443\u0442\u044C \u043F\u0440\u0438\u0445\u043E\u0432\u0430\u043D\u0456 \u0443 \u0441\u043F\u0438\u0441\u043A\u0443 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0456\u0432",
    "settings.providers.disabled.enable": "\u0423\u0432\u0456\u043C\u043A\u043D\u0443\u0442\u0438",
