    "settings.agentBehaviour.permissions.hint": "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u043E\u0446\u0456\u043D\u044E\u044E\u0442\u044C\u0441\u044F \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u2014 \u043E\u0441\u0442\u0430\u043D\u043D\u0454 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u043C\u0430\u0454 \u043F\u0440\u0456\u043E\u0440\u0438\u0442\u0435\u0442. \u0426\u0435 \u0440\u043E\u0437\u0440\u0430\u0445\u043E\u0432\u0430\u043D\u0438\u0439 \u043D\u0430\u0431\u0456\u0440 \u043F\u0440\u0430\u0432\u0438\u043B \u0437 CLI \u0431\u0435\u043A\u0435\u043D\u0434\u0443.",
    "settings.agentBehaviour.editMode.save": "\u0413\u043E\u0442\u043E\u0432\u043E",
    "diffViewer.source.workspace.label": "\u0413\u0456\u043B\u043A\u0430",
    "diffViewer.source.workspace.tooltip": "\u0423\u0441\u0456 \u0437\u043C\u0456\u043D\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0456\u043B\u0446\u0456 \u043F\u043E\u0440\u0456\u0432\u043D\u044F\u043D\u043E \u0437 \u0431\u0430\u0437\u043E\u0432\u043E\u044E. \u0412\u043A\u043B\u044E\u0447\u0430\u0454 \u043D\u0435\u0437\u0430\u043A\u043E\u043C\u0456\u0447\u0435\u043D\u0456 \u0444\u0430\u0439\u043B\u0438 (staged, unstaged, \u043D\u0435\u0432\u0456\u0434\u0441\u0442\u0435\u0436\u0443\u0432\u0430\u043D\u0456) \u0442\u0430 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0456 \u043A\u043E\u043C\u0456\u0442\u0438, \u044F\u043A\u0438\u0445 \u0449\u0435 \u043D\u0435\u043C\u0430\u0454 \u0432 \u0431\u0430\u0437\u0456.",
    "diffViewer.source.staged.label": "Staged",
    "diffViewer.source.staged.tooltip": "\u0424\u0430\u0439\u043B\u0438 \u0437\u0456 \u0437\u043C\u0456\u043D\u0430\u043C\u0438, \u0434\u043E\u0434\u0430\u043D\u0438\u043C\u0438 \u0434\u043E \u043E\u0431\u043B\u0430\u0441\u0442\u0456 \u043F\u0456\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0438 git (`git add`), \u044F\u043A \u0432\u043E\u043D\u0438 \u0437'\u044F\u0432\u043B\u044F\u0442\u044C\u0441\u044F \u0432 \u043D\u0430\u0441\u0442\u0443\u043F\u043D\u043E\u043C\u0443 \u043A\u043E\u043C\u0456\u0442\u0456.",
    "diffViewer.source.unstaged.label": "Unstaged",
    "diffViewer.source.unstaged.tooltip": "\u0424\u0430\u0439\u043B\u0438, \u0437\u043C\u0456\u043D\u0435\u043D\u0456 \u0432 \u0440\u043E\u0431\u043E\u0447\u043E\u043C\u0443 \u0434\u0435\u0440\u0435\u0432\u0456, \u0430\u043B\u0435 \u0449\u0435 \u043D\u0435 \u043F\u0456\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u0456, \u043F\u043B\u044E\u0441 \u043D\u0435\u0432\u0456\u0434\u0441\u0442\u0435\u0436\u0443\u0432\u0430\u043D\u0456 (\u043D\u043E\u0432\u0456) \u0444\u0430\u0439\u043B\u0438.",
    "diffViewer.source.session.label": "\u0421\u0435\u0441\u0456\u044F",
    "diffViewer.source.session.tooltip": "\u0424\u0430\u0439\u043B\u0438, \u0437\u043C\u0456\u043D\u0435\u043D\u0456 Kilo \u043F\u0456\u0434 \u0447\u0430\u0441 \u043F\u043E\u0442\u043E\u0447\u043D\u043E\u0457 \u0441\u0435\u0441\u0456\u0457, \u043D\u0430 \u043E\u0441\u043D\u043E\u0432\u0456 \u0437\u043D\u0456\u043C\u043A\u0456\u0432 \u043F\u043E \u0445\u043E\u0434\u0443. \u0421\u043A\u0438\u0434\u0430\u0454\u0442\u044C\u0441\u044F \u043F\u0440\u0438 \u0441\u0442\u0430\u0440\u0442\u0456 \u043D\u043E\u0432\u043E\u0457 \u0441\u0435\u0441\u0456\u0457.",
    "diffViewer.group.session": "\u0421\u0435\u0441\u0456\u044F",
    "diffViewer.group.git": "Git",
    "diffViewer.notice.snapshotsDisabled": "\u0417\u043D\u0456\u043C\u043A\u0438 \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u044E. \u0411\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u0432\u0456\u0434\u0440\u0435\u0434\u0430\u0433\u0443\u0439\u0442\u0435 \u0444\u0430\u0439\u043B\u0438 \u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0457, \u0449\u043E\u0431 \u0432\u0456\u0434\u043E\u0431\u0440\u0430\u0436\u0430\u0442\u0438 \u0437\u043C\u0456\u043D\u0438 \u0441\u0435\u0441\u0456\u0457.",
