    "marketplace.install.learnMcp": "\u041F\u043E\u0434\u0440\u043E\u0431\u043D\u0435\u0435 \u043E MCP",
    "marketplace.install.installedAt": "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u0432 {{path}}",
    "marketplace.intro": "\u0423\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0439\u0442\u0435 \u043C\u043D\u043E\u0433\u043E\u043A\u0440\u0430\u0442\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u043C\u044B\u0445 \u0430\u0433\u0435\u043D\u0442\u043E\u0432, \u043D\u0430\u0432\u044B\u043A\u0438 \u0438 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B MCP \u0434\u043B\u044F \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u043B\u0438 \u0432\u0441\u0435\u0445 \u043F\u0440\u043E\u0435\u043A\u0442\u043E\u0432.",
