    "snapshot.slowRepo.header": "\u0627\u0644\u0644\u0642\u0637\u0629 \u0628\u0637\u064A\u0626\u0629",
    "snapshot.slowRepo.question": "\u064A\u0633\u062A\u063A\u0631\u0642 \u062A\u0647\u064A\u0626\u0629 \u0646\u0638\u0627\u0645 \u0627\u0644\u0644\u0642\u0637\u0627\u062A \u0648\u0642\u062A\u064B\u0627 \u0637\u0648\u064A\u0644\u0627\u064B\u060C \u063A\u0627\u0644\u0628\u064B\u0627 \u0628\u0633\u0628\u0628 \u062D\u062C\u0645 \u0627\u0644\u0645\u0633\u062A\u0648\u062F\u0639.\n\n\u0647\u0644 \u062A\u0631\u064A\u062F \u062A\u0639\u0637\u064A\u0644 \u0627\u0644\u0644\u0642\u0637\u0627\u062A \u0644\u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062A\u0648\u062F\u0639\u061F",
