    // Slow-repo snapshot prompt
    "snapshot.slowRepo.header": "\u0417\u043D\u0456\u043C\u043E\u043A \u0432\u0438\u043A\u043E\u043D\u0443\u0454\u0442\u044C\u0441\u044F \u043F\u043E\u0432\u0456\u043B\u044C\u043D\u043E",
    "snapshot.slowRepo.question": "\u0406\u043D\u0456\u0446\u0456\u0430\u043B\u0456\u0437\u0430\u0446\u0456\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0438 \u0437\u043D\u0456\u043C\u043A\u0456\u0432 \u0437\u0430\u0439\u043C\u0430\u0454 \u0431\u0430\u0433\u0430\u0442\u043E \u0447\u0430\u0441\u0443, \u0439\u043C\u043E\u0432\u0456\u0440\u043D\u043E, \u0447\u0435\u0440\u0435\u0437 \u0440\u043E\u0437\u043C\u0456\u0440 \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u044E.\n\n\u0412\u0438\u043C\u043A\u043D\u0443\u0442\u0438 \u0437\u043D\u0456\u043C\u043A\u0438 \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u044E?",
    "snapshot.slowRepo.answer.continue": "\u041F\u0440\u043E\u0434\u043E\u0432\u0436\u0438\u0442\u0438 \u0437\u0456 \u0437\u043D\u0456\u043C\u043A\u0430\u043C\u0438",
    "snapshot.slowRepo.answer.continue.description": "\u0417\u0430\u0447\u0435\u043A\u0430\u0439\u0442\u0435, \u043F\u043E\u043A\u0438 \u0437\u043D\u0456\u043C\u043E\u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C\u0441\u044F. \u041D\u0430\u0441\u0442\u0443\u043F\u043D\u0456 \u0445\u043E\u0434\u0438 \u0431\u0443\u0434\u0443\u0442\u044C \u0448\u0432\u0438\u0434\u043A\u0438\u043C\u0438, \u0449\u043E\u0439\u043D\u043E \u043F\u043E\u0447\u0430\u0442\u043A\u043E\u0432\u0438\u0439 \u0437\u043D\u0456\u043C\u043E\u043A \u0431\u0443\u0434\u0435 \u0441\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u0439.",
    "snapshot.slowRepo.answer.disable": "\u0412\u0438\u043C\u043A\u043D\u0443\u0442\u0438 \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u043F\u0440\u043E\u0454\u043A\u0442\u0443",
    "snapshot.slowRepo.answer.disable.description": "\u0412\u0438\u043C\u043A\u043D\u0456\u0442\u044C \u0437\u043D\u0456\u043C\u043A\u0438 Kilo \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u043F\u0440\u043E\u0454\u043A\u0442\u0443. \u0412\u0438 \u0432\u0442\u0440\u0430\u0442\u0438\u0442\u0435 \u0441\u043A\u0430\u0441\u0443\u0432\u0430\u043D\u043D\u044F/\u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u043D\u044F \u0434\u043B\u044F \u0437\u043C\u0456\u043D Kilo, \u0430\u043B\u0435 git \u043F\u0440\u043E\u0434\u043E\u0432\u0436\u0438\u0442\u044C \u0432\u0456\u0434\u0441\u0442\u0435\u0436\u0443\u0432\u0430\u0442\u0438 \u0432\u0441\u0435.",
